class Provider implements CustomSource {
    base_url = "https://www.webtoons.com"
    mobile_url = "https://m.webtoons.com"
    language_path = "en"

    getSettings(): Settings {
        return {
            supportsAnime: false,
            supportsManga: true,
        }
    }

    async getAnime(ids: number[]): Promise<$app.AL_BaseAnime[]> {
        return []
    }

    async getAnimeDetails(id: number): Promise<$app.AL_AnimeDetailsById_Media | null> {
        return null
    }

    async getAnimeMetadata(id: number): Promise<$app.Metadata_AnimeMetadata | null> {
        return null
    }

    async getAnimeWithRelations(id: number): Promise<$app.AL_CompleteAnime> {
        throw new Error("Anime is not supported by the WEBTOON source.")
    }

    async listAnime(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseAnime>> {
        return {
            media: [],
            total: 0,
            page: 1,
            totalPages: 1,
        }
    }

    async getManga(ids: number[]): Promise<$app.AL_BaseManga[]> {
        const ret: $app.AL_BaseManga[] = []
        const cache = this._getMangaCache()

        for (const id of ids) {
            const cached = cache[id]

            if (cached && cached.media && !this._isPlaceholder(cached.media, id)) {
                ret.push(cached.media)
                continue
            }

            try {
                const detailed = await this._getSeriesFromInput(
                    `${this._baseUrl()}/episodeList?titleNo=${id}`, id)
                if (detailed) {
                    const stored = this._seriesToStoredManga(detailed)
                    cache[stored.titleNo] = stored
                    ret.push(stored.media)
                    continue
                }
            } catch (err) {
                console.error("WEBTOON getManga fetch failed:", err)
            }

            // Do not cache the placeholder; a later request retries the live fetch.
            ret.push(this._makeFallbackManga(id))
        }

        this._setMangaCache(cache)

        return ret
    }

    private _isPlaceholder(media: any, id: number): boolean {
        const title = media && media.title && media.title.userPreferred
        return typeof title === "string" && title === `WEBTOON ${id}`
    }

    async getMangaDetails(id: number): Promise<$app.AL_MangaDetailsById_Media | null> {
        const cache = this._getMangaCache()
        let cached = cache[id]

        if (!cached) {
            const manga = await this.getManga([id])
            if (!manga || manga.length === 0) return null
            cached = this._getMangaCache()[id]
        }

        if (!cached || !cached.media) return null

        return cached.media as any
    }

    async listManga(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseManga>> {
        const query = String(search || "").trim()
        const currentPage = page && page > 0 ? page : 1
        const limit = Math.max(1, Math.min(perPage || 20, 20))

        let results: WebtoonSeries[] = []

        if (query.length > 0) {
            const directId = this._getTitleNo(query)

            if (directId > 0) {
                const directUrl = query.indexOf("webtoons.com") >= 0
                    ? query
                    : this._searchUrl(String(directId), 1)

                const direct = await this._getSeriesFromInput(directUrl, directId)

                if (direct) {
                    results = [direct]
                } else {
                    results = await this._searchWebtoons(query, currentPage, limit)
                }
            } else {
                results = await this._searchWebtoons(query, currentPage, limit)
            }
        } else {
            results = await this._getPopularWebtoons(currentPage, limit)
        }

        results = this._dedupeSeries(results).slice(0, limit)

        const cache = this._getMangaCache()
        const media: $app.AL_BaseManga[] = []

        for (const item of results) {
            const stored = this._seriesToStoredManga(item)
            cache[stored.titleNo] = stored
            media.push(stored.media)
        }

        this._setMangaCache(cache)

        return {
            media: media,
            total: query.length > 0 ? Math.max(media.length, currentPage * limit + media.length) : media.length,
            page: currentPage,
            totalPages: media.length >= limit ? currentPage + 1 : Math.max(1, currentPage),
        }
    }

    private async _searchWebtoons(query: string, page: number, limit: number): Promise<WebtoonSeries[]> {
        const urls = [
            this._searchUrl(query, page),
            this._mobileSearchUrl(query),
        ]

        for (const url of urls) {
            try {
                console.log("WEBTOON search:", url)

                const html = await this._fetchText(url)

                if (!html || html.length < 200) {
                    continue
                }

                const links = this._parseSeriesLinks(html)

                if (links.length === 0) {
                    continue
                }

                const detailed = await this._hydrateSeriesLinks(links, limit)

                if (detailed.length > 0) {
                    return detailed
                }
            } catch (err) {
                console.error("WEBTOON search failed:", err)
            }
        }

        return []
    }

    private async _getPopularWebtoons(page: number, limit: number): Promise<WebtoonSeries[]> {
        const urls = [
            `${this._baseUrl()}/${this._lang()}/`,
            `${this._baseUrl()}/${this._lang()}/dailySchedule`,
            `${this._baseUrl()}/${this._lang()}/genres`,
            `${this._baseUrl()}/${this._lang()}/originals`,
            `${this._mobileUrl()}/${this._lang()}/`,
        ]

        for (const url of urls) {
            try {
                console.log("WEBTOON popular:", url)

                const html = await this._fetchText(url)

                if (!html || html.length < 200) {
                    continue
                }

                const links = this._parseSeriesLinks(html)

                if (links.length === 0) {
                    continue
                }

                const start = Math.max(0, (page - 1) * limit)
                const pagedLinks = links.slice(start, start + limit)

                const detailed = await this._hydrateSeriesLinks(pagedLinks, limit)

                if (detailed.length > 0) {
                    return detailed
                }
            } catch (err) {
                console.error("WEBTOON popular failed:", err)
            }
        }

        return []
    }

    private async _hydrateSeriesLinks(links: WebtoonLink[], limit: number): Promise<WebtoonSeries[]> {
        const ret: WebtoonSeries[] = []
        const seen: any = {}

        for (const link of links) {
            if (!link || !link.titleNo || seen[link.titleNo]) {
                continue
            }

            seen[link.titleNo] = true

            const detailed = await this._getSeriesFromInput(link.url, link.titleNo)

            if (detailed) {
                if (!detailed.title && link.title) detailed.title = link.title
                ret.push(detailed)
            } else {
                ret.push({
                    titleNo: link.titleNo,
                    title: link.title || `WEBTOON ${link.titleNo}`,
                    author: "WEBTOON",
                    url: link.url,
                    thumbnail: link.thumbnail || "",
                    banner: link.thumbnail || "",
                    description: "",
                    genre: "WEBTOON",
                    status: "FINISHED",
                    viewsText: "",
                    subscribeText: "",
                    chapterCount: 1,
                    chapters: [],
                })
            }

            if (ret.length >= limit) {
                break
            }
        }

        return ret
    }

    private async _getSeriesFromInput(input: string, fallbackTitleNo: number): Promise<WebtoonSeries | null> {
        const url = this._normalizeUrl(input)

        if (!url || url.indexOf("webtoons.com") < 0) {
            return null
        }

        try {
            const html = await this._fetchText(url)

            if (!html || html.length < 200) {
                return null
            }

            return this._parseSeriesPage(html, url, fallbackTitleNo)
        } catch (err) {
            console.error("WEBTOON detail fetch failed:", err)
            return null
        }
    }

    private _parseSeriesPage(html: string, pageUrl: string, fallbackTitleNo: number): WebtoonSeries | null {
        const titleNo = this._getTitleNo(pageUrl) || fallbackTitleNo

        if (!titleNo) {
            return null
        }

        const ogTitle = this._meta(html, "og:title")
        const ogDescription = this._meta(html, "og:description")
        const ogImage = this._meta(html, "og:image")

        let title =
            this._decode(this._stripBrand(ogTitle)) ||
            this._decode(this._firstMatch(html, /<h1[^>]*>([\s\S]*?)<\/h1>/i)) ||
            `WEBTOON ${titleNo}`

        title = this._cleanText(title)

        const genre =
            this._cleanText(this._firstMatch(html, /<h2[^>]*class=["'][^"']*genre[^"']*["'][^>]*>([\s\S]*?)<\/h2>/i)) ||
            this._cleanText(this._firstMatch(html, /<h2[^>]*>([\s\S]*?)<\/h2>/i)) ||
            "WEBTOON"

        const author =
            this._cleanText(this._firstMatch(html, /<a[^>]*class=["'][^"']*author[^"']*["'][^>]*>([\s\S]*?)<\/a>/i)) ||
            this._cleanText(this._firstMatch(html, /<span[^>]*class=["'][^"']*author[^"']*["'][^>]*>([\s\S]*?)<\/span>/i)) ||
            this._cleanText(this._firstMatch(html, /<p[^>]*class=["'][^"']*author[^"']*["'][^>]*>([\s\S]*?)<\/p>/i)) ||
            this._guessAuthorFromText(html) ||
            "WEBTOON"

        const description =
            this._cleanText(ogDescription) ||
            this._cleanText(this._firstMatch(html, /<p[^>]*class=["'][^"']*summary[^"']*["'][^>]*>([\s\S]*?)<\/p>/i)) ||
            this._cleanText(this._firstMatch(html, /<p[^>]*class=["'][^"']*subj[^"']*["'][^>]*>([\s\S]*?)<\/p>/i)) ||
            ""

        const thumbnail =
            this._normalizeUrl(ogImage) ||
            this._normalizeUrl(this._firstMatch(html, /<img[^>]+class=["'][^"']*detail[^"']*["'][^>]+src=["']([^"']+)["']/i)) ||
            ""

        const viewsText =
            this._cleanText(this._firstMatch(html, /<li[^>]*>\s*view\s*([\s\S]*?)<\/li>/i)) ||
            this._cleanText(this._firstMatch(html, /view\s*([0-9.,]+[KMB]?)/i))

        const subscribeText =
            this._cleanText(this._firstMatch(html, /<li[^>]*>\s*subscribe\s*([\s\S]*?)<\/li>/i)) ||
            this._cleanText(this._firstMatch(html, /subscribe\s*([0-9.,]+[KMB]?)/i))

        const chapters = this._parseChapters(html, pageUrl, titleNo)

        let chapterCount = chapters.length

        for (const ch of chapters) {
            if (ch.number > chapterCount) {
                chapterCount = ch.number
            }
        }

        if (chapterCount <= 0) {
            chapterCount = this._parseChapterCountFromText(html)
        }

        if (chapterCount <= 0) {
            chapterCount = 1
        }

        const status = this._statusFromHtml(html)

        return {
            titleNo: titleNo,
            title: title,
            author: author,
            url: pageUrl,
            thumbnail: thumbnail,
            banner: thumbnail,
            description: description,
            genre: genre,
            status: status,
            viewsText: viewsText,
            subscribeText: subscribeText,
            chapterCount: chapterCount,
            chapters: chapters,
        }
    }

    private _parseSeriesLinks(html: string): WebtoonLink[] {
        const ret: WebtoonLink[] = []
        const seen: any = {}

        const linkPattern = /<a[^>]+href=["']([^"']*\/list\?title_no=([0-9]+)[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi

        let match: RegExpExecArray | null

        while ((match = linkPattern.exec(html)) !== null) {
            const href = this._decode(match[1] || "")
            const titleNo = Number(match[2] || 0)
            const inner = match[3] || ""

            if (!titleNo || seen[titleNo]) {
                continue
            }

            seen[titleNo] = true

            const title =
                this._cleanText(this._firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this._cleanText(this._firstMatch(inner, /alt=["']([^"']+)["']/i)) ||
                this._cleanText(inner)

            const thumbnail =
                this._normalizeUrl(this._decode(this._firstMatch(inner, /data-src=["']([^"']+)["']/i))) ||
                this._normalizeUrl(this._decode(this._firstMatch(inner, /src=["']([^"']+)["']/i))) ||
                ""

            ret.push({
                titleNo: titleNo,
                title: title,
                url: this._normalizeUrl(href),
                thumbnail: thumbnail,
            })
        }

        const rawUrlPattern = /https?:\/\/(?:www\.|m\.)?webtoons\.com\/[^"'\s<>]+\/list\?title_no=([0-9]+)/gi

        while ((match = rawUrlPattern.exec(html)) !== null) {
            const rawUrl = match[0]
            const titleNo = Number(match[1] || 0)

            if (!titleNo || seen[titleNo]) {
                continue
            }

            seen[titleNo] = true

            ret.push({
                titleNo: titleNo,
                title: "",
                url: this._normalizeUrl(rawUrl),
                thumbnail: "",
            })
        }

        return ret
    }

    private _parseChapters(html: string, pageUrl: string, titleNo: number): WebtoonChapter[] {
        const ret: WebtoonChapter[] = []
        const seen: any = {}

        const pattern = /<a[^>]+href=["']([^"']*\/viewer\?title_no=([0-9]+)&episode_no=([0-9]+)[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi

        let match: RegExpExecArray | null

        while ((match = pattern.exec(html)) !== null) {
            const href = this._decode(match[1] || "")
            const foundTitleNo = Number(match[2] || 0)
            const episodeNo = Number(match[3] || 0)
            const inner = match[4] || ""

            if (!episodeNo || foundTitleNo !== titleNo || seen[episodeNo]) {
                continue
            }

            seen[episodeNo] = true

            const title =
                this._cleanText(this._firstMatch(inner, /title=["']([^"']+)["']/i)) ||
                this._cleanText(this._firstMatch(inner, /<span[^>]*class=["'][^"']*subj[^"']*["'][^>]*>([\s\S]*?)<\/span>/i)) ||
                this._cleanText(this._firstMatch(inner, /<p[^>]*class=["'][^"']*subj[^"']*["'][^>]*>([\s\S]*?)<\/p>/i)) ||
                this._cleanText(inner) ||
                `Episode ${episodeNo}`

            const date =
                this._cleanText(this._firstMatch(inner, /([A-Z][a-z]{2}\s+[0-9]{1,2},\s+[0-9]{4})/i)) ||
                ""

            const thumbnail =
                this._normalizeUrl(this._decode(this._firstMatch(inner, /data-src=["']([^"']+)["']/i))) ||
                this._normalizeUrl(this._decode(this._firstMatch(inner, /src=["']([^"']+)["']/i))) ||
                ""

            ret.push({
                number: episodeNo,
                title: title,
                url: this._normalizeUrl(href || pageUrl),
                thumbnail: thumbnail,
                date: date,
            })
        }

        ret.sort((a, b) => a.number - b.number)

        return ret
    }

    private _seriesToStoredManga(series: WebtoonSeries): StoredWebtoonManga {
        const title = series.title || `WEBTOON ${series.titleNo}`
        const author = series.author || "WEBTOON"
        const cover = series.thumbnail || ""
        const banner = series.banner || cover

        const descriptionParts: string[] = []

        if (series.description) descriptionParts.push(series.description)
        if (series.viewsText) descriptionParts.push(`Views: ${series.viewsText}`)
        if (series.subscribeText) descriptionParts.push(`Subscribers: ${series.subscribeText}`)
        descriptionParts.push(`WEBTOON: ${series.url}`)

        const description = this._truncate(descriptionParts.join("\n\n"), 4000)

        const media: $app.AL_BaseManga = {
            id: series.titleNo,
            siteUrl: series.url,
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: title,
            },
            coverImage: {
                large: cover,
                medium: cover,
                extraLarge: cover,
                color: "",
            },
            bannerImage: banner,
            description: description,
            genres: this._genres(series.genre, author),
            meanScore: 0,
            synonyms: [author],
            status: series.status,
            chapters: series.chapterCount || 1,
            volumes: undefined,
            type: "MANGA",
            format: "MANGA",
            countryOfOrigin: "KR",
            isAdult: false,
            startDate: {
                year: new Date().getUTCFullYear(),
            },
            endDate: undefined,
        } as any

        return {
            titleNo: series.titleNo,
            url: series.url,
            media: media,
            chapters: series.chapters || [],
        }
    }

    private _makeFallbackManga(id: number): $app.AL_BaseManga {
        const title = `WEBTOON ${id}`

        return {
            id: id,
            siteUrl: this._searchUrl(String(id), 1),
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: title,
            },
            coverImage: {
                large: "",
                medium: "",
                extraLarge: "",
                color: "",
            },
            bannerImage: "",
            description: "This WEBTOON was not in the cache. Search for it again to reload full metadata.",
            genres: ["WEBTOON"],
            meanScore: 0,
            synonyms: [],
            status: "FINISHED",
            chapters: 1,
            volumes: undefined,
            type: "MANGA",
            format: "MANGA",
            countryOfOrigin: "KR",
            isAdult: false,
            startDate: {
                year: new Date().getUTCFullYear(),
            },
            endDate: undefined,
        } as any
    }

    private _searchUrl(query: string, page: number): string {
        return `${this._baseUrl()}/${this._lang()}/search?keyword=${encodeURIComponent(query)}&page=${encodeURIComponent(String(page || 1))}`
    }

    private _mobileSearchUrl(query: string): string {
        return `${this._mobileUrl()}/${this._lang()}/search?keyword=${encodeURIComponent(query)}`
    }

    private async _fetchText(url: string): Promise<string> {
        const res = await fetch(url, {
            headers: {
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                "Accept-Language": "en-US,en;q=0.9",
                "User-Agent": "Mozilla/5.0",
            },
        })

        if (!res.ok) {
            throw new Error(`HTTP ${res.status} for ${url}`)
        }

        return await res.text()
    }

    private _meta(html: string, property: string): string {
        const p1 = new RegExp(`<meta[^>]+property=["']${this._escapeRegExp(property)}["'][^>]+content=["']([^"']+)["']`, "i")
        const p2 = new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+property=["']${this._escapeRegExp(property)}["']`, "i")
        const p3 = new RegExp(`<meta[^>]+name=["']${this._escapeRegExp(property)}["'][^>]+content=["']([^"']+)["']`, "i")

        return this._decode(this._firstMatch(html, p1) || this._firstMatch(html, p2) || this._firstMatch(html, p3))
    }

    private _getTitleNo(input: string): number {
        const text = String(input || "")

        const patterns = [
            /title_no=([0-9]+)/i,
            /titleNo=([0-9]+)/i,
            /^([0-9]+)$/,
        ]

        for (const pattern of patterns) {
            const match = text.match(pattern)
            if (match && match[1]) {
                return Number(match[1]) || 0
            }
        }

        return 0
    }

    private _parseChapterCountFromText(html: string): number {
        let max = 0
        const pattern = /episode_no=([0-9]+)/gi
        let match: RegExpExecArray | null

        while ((match = pattern.exec(html)) !== null) {
            const n = Number(match[1] || 0)
            if (n > max) max = n
        }

        const hashPattern = /#\s*([0-9]{1,5})/g

        while ((match = hashPattern.exec(html)) !== null) {
            const n = Number(match[1] || 0)
            if (n > max) max = n
        }

        return max
    }

    private _statusFromHtml(html: string): string {
        const text = this._cleanText(html).toLowerCase()

        if (
            text.indexOf("up every") >= 0 ||
            text.indexOf("updates every") >= 0 ||
            text.indexOf("will return") >= 0 ||
            text.indexOf("returning") >= 0
        ) {
            return "RELEASING"
        }

        if (
            text.indexOf("completed") >= 0 ||
            text.indexOf("series finale") >= 0 ||
            text.indexOf("finale") >= 0
        ) {
            return "FINISHED"
        }

        return "FINISHED"
    }

    private _guessAuthorFromText(html: string): string {
        const cleaned = this._cleanText(html)
        const match = cleaned.match(/([A-Za-z0-9 ._'&-]{2,80})\s+author info/i)

        if (match && match[1]) {
            return this._cleanText(match[1])
        }

        return ""
    }

    private _genres(genre: string, author: string): string[] {
        const ret: string[] = []

        if (genre) ret.push(genre)
        ret.push("WEBTOON")

        if (author && author !== "WEBTOON") {
            ret.push(author)
        }

        return ret
    }

    private _baseUrl(): string {
        let url = String(this.base_url || "https://www.webtoons.com").trim()

        if (url.indexOf("{{") >= 0 || url.indexOf("}}") >= 0) {
            url = "https://www.webtoons.com"
        }

        return this._trimSlash(url)
    }

    private _mobileUrl(): string {
        let url = String(this.mobile_url || "https://m.webtoons.com").trim()

        if (url.indexOf("{{") >= 0 || url.indexOf("}}") >= 0) {
            url = "https://m.webtoons.com"
        }

        return this._trimSlash(url)
    }

    private _lang(): string {
        const lang = String(this.language_path || "en").trim()

        if (!lang || lang.indexOf("{{") >= 0 || lang.indexOf("}}") >= 0) {
            return "en"
        }

        return lang
    }

    private _normalizeUrl(url: string): string {
        let value = this._decode(String(url || "").trim())

        if (!value) return ""

        value = value.replace(/&amp;/g, "&")

        if (value.indexOf("//") === 0) {
            return "https:" + value
        }

        if (value.indexOf("/") === 0) {
            return this._baseUrl() + value
        }

        if (value.indexOf("http") === 0) {
            return value
        }

        return this._baseUrl() + "/" + value
    }

    private _stripBrand(input: string): string {
        return String(input || "")
            .replace(/\s*\|\s*WEBTOON\s*$/i, "")
            .replace(/\s*-\s*WEBTOON\s*$/i, "")
            .trim()
    }

    private _firstMatch(text: string, pattern: RegExp): string {
        const match = String(text || "").match(pattern)
        return match && match[1] ? match[1] : ""
    }

    private _cleanText(input: string): string {
        return this._decode(
            String(input || "")
                .replace(/<script[\s\S]*?<\/script>/gi, " ")
                .replace(/<style[\s\S]*?<\/style>/gi, " ")
                .replace(/<[^>]+>/g, " ")
                .replace(/\s+/g, " ")
                .trim(),
        )
    }

    private _decode(input: string): string {
        return String(input || "")
            .replace(/&amp;/g, "&")
            .replace(/&quot;/g, "\"")
            .replace(/&#39;/g, "'")
            .replace(/&apos;/g, "'")
            .replace(/&lt;/g, "<")
            .replace(/&gt;/g, ">")
            .replace(/&#x2F;/g, "/")
            .replace(/&#47;/g, "/")
            .replace(/&nbsp;/g, " ")
    }

    private _escapeRegExp(input: string): string {
        return String(input || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    }

    private _trimSlash(input: string): string {
        let value = String(input || "").trim()

        while (value.endsWith("/")) {
            value = value.slice(0, -1)
        }

        return value
    }

    private _dedupeSeries(series: WebtoonSeries[]): WebtoonSeries[] {
        const seen: any = {}
        const ret: WebtoonSeries[] = []

        for (const item of series) {
            if (!item || !item.titleNo || seen[item.titleNo]) {
                continue
            }

            seen[item.titleNo] = true
            ret.push(item)
        }

        return ret
    }

    private _truncate(input: string, max: number): string {
        if (!input) return ""
        if (input.length <= max) return input
        return input.slice(0, max - 3) + "..."
    }

    private _getMangaCache(): any {
        return ($store.get("webtoon.manga") as any) || {}
    }

    private _setMangaCache(cache: any) {
        $store.set("webtoon.manga", cache)
    }
}

type StoredWebtoonManga = {
